"use server";

import { Prisma } from "@/generated/prisma/client";
import { prisma } from "@/shared/lib/prisma";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import bcrypt from "bcrypt";

export const createUser = async (formData) => {

    try {
        const data = {
            userName : formData.get("userName"),
            userType: formData.get("userType"),
            password : formData.get("password"),
            confirmPassword : formData.get("confirmPassword")
        };

        const UserExist = prisma.AdminUser.findUniqueOrThrow({
            where : {
                userName : data.userName    
            }
        })

        const salt = bcrypt.genSaltSync(10);
        const hashedPassword = await bcrypt.hash(formData.get("password"), salt);

        await prisma.AdminUser.create({
            data: {
                userName : data.userName,
                userType : data.userType,
                password : hashedPassword
            }
        });

        revalidatePath("/users", "index");
        redirect('/users');
    } catch {
        if(Prisma.PrismaClientKnownRequestError) {
            return redirect(`/users/add?errorMessage=Userame already exists`);
        }
    }
}